  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "risk" TEXT NOT NULL,
  "revision" INTEGER NOT NULL,
  "predecessor" TEXT,
  "likelihood" TEXT NOT NULL,
  "impact" TEXT NOT NULL,
  "confidence" INTEGER NOT NULL,
  "evaluation" TEXT NOT NULL,
  "support" TEXT NOT NULL,
  "assessed_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, risk) REFERENCES risk (tenant, id),
  FOREIGN KEY (tenant, predecessor) REFERENCES risk_assessment (tenant, id),
  FOREIGN KEY (tenant, likelihood) REFERENCES risk_level (tenant, id),
  FOREIGN KEY (tenant, impact) REFERENCES risk_level (tenant, id),
  FOREIGN KEY (tenant, evaluation) REFERENCES evaluation_finish (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE risk_level (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "scale" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  "rank" INTEGER NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, scale) REFERENCES risk_scale (tenant, id)
);

CREATE TABLE risk_scale (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE risk_treatment (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "assessment" TEXT NOT NULL,
  "fulfillment_set" TEXT NOT NULL,
  "action" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, assessment) REFERENCES risk_assessment (tenant, id),
  FOREIGN KEY (tenant, fulfillment_set) REFERENCES fulfillment_set (tenant, id)
);

CREATE TABLE realization (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "pin" TEXT NOT NULL,
  "build_hash" TEXT NOT NULL,
  "manifest_digest" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, pin) REFERENCES specification_pin (tenant, id)
);

CREATE TABLE repository (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "provider" TEXT NOT NULL,
  "locator" TEXT NOT NULL,
  "version" INTEGER NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE specification_pin (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "repository" TEXT NOT NULL,
  "anchor" TEXT NOT NULL,
  "revision" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, repository) REFERENCES repository (tenant, id)
);

CREATE TABLE dispute_resolution (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "dispute" TEXT NOT NULL,
  "upheld" INTEGER NOT NULL,
  "effective_at" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "support" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, dispute) REFERENCES signal_dispute (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE party_subject (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "subject" TEXT NOT NULL,
  "party" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, subject) REFERENCES trust_subject (tenant, id),
  FOREIGN KEY (tenant, party) REFERENCES party (tenant, id)
);

CREATE TABLE risk_trust_input (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "assessment" TEXT NOT NULL,
  "trust" TEXT NOT NULL,
  "rationale" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, assessment) REFERENCES risk_assessment (tenant, id),
  FOREIGN KEY (tenant, trust) REFERENCES trust_assessment (tenant, id)
);

CREATE TABLE signal_correction (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "signal" TEXT NOT NULL,
  "replacement" TEXT,
  "effective_at" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "support" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, signal) REFERENCES trust_signal (tenant, id),
  FOREIGN KEY (tenant, replacement) REFERENCES trust_signal (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE signal_dispute (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "signal" TEXT NOT NULL,
  "raised_by" TEXT NOT NULL,
  "effective_at" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "support" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, signal) REFERENCES trust_signal (tenant, id),
  FOREIGN KEY (tenant, raised_by) REFERENCES party (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE signal_kind (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "dimension" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "definition" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, dimension) REFERENCES trust_dimension (tenant, id),
  FOREIGN KEY (tenant, definition) REFERENCES specification_pin (tenant, id)
);

CREATE TABLE signal_member (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "signal" TEXT NOT NULL,
  "rationale" TEXT NOT NULL,
  "next" TEXT,
  "depth" INTEGER NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, signal) REFERENCES trust_signal (tenant, id),
  FOREIGN KEY (tenant, next) REFERENCES signal_member (tenant, id)
);

CREATE TABLE trust_assessment (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "review" TEXT NOT NULL,
  "dimension" TEXT NOT NULL,
  "run" TEXT NOT NULL,
  "finish" TEXT NOT NULL,
  "score" INTEGER NOT NULL,
  "confidence" INTEGER NOT NULL,
  "explanation" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, review) REFERENCES trust_review (tenant, id),
  FOREIGN KEY (tenant, dimension) REFERENCES trust_dimension (tenant, id),
  FOREIGN KEY (tenant, run) REFERENCES evaluation_run (tenant, id),
  FOREIGN KEY (tenant, finish) REFERENCES evaluation_finish (tenant, id)
);

CREATE TABLE trust_dimension (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "context" TEXT NOT NULL,
  "method" TEXT NOT NULL,
  "minimum" INTEGER NOT NULL,
  "maximum" INTEGER NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, method) REFERENCES specification_pin (tenant, id)
);

CREATE TABLE trust_review (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "subject" TEXT NOT NULL,
  "dimension" TEXT NOT NULL,
  "window_from" TEXT NOT NULL,
  "window_until" TEXT NOT NULL,
  "evaluations" TEXT NOT NULL,
  "head" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, subject) REFERENCES trust_subject (tenant, id),
  FOREIGN KEY (tenant, dimension) REFERENCES trust_dimension (tenant, id),
  FOREIGN KEY (tenant, evaluations) REFERENCES evaluation_set (tenant, id),
  FOREIGN KEY (tenant, head) REFERENCES signal_member (tenant, id)
);

CREATE TABLE trust_signal (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "subject" TEXT NOT NULL,
  "dimension" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "issuer" TEXT NOT NULL,
  "source_record" TEXT NOT NULL,
  "observed_at" TEXT NOT NULL,
  "support" TEXT NOT NULL,
  "explanation" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, subject) REFERENCES trust_subject (tenant, id),
  FOREIGN KEY (tenant, dimension) REFERENCES trust_dimension (tenant, id),
  FOREIGN KEY (tenant, kind) REFERENCES signal_kind (tenant, id),
  FOREIGN KEY (tenant, issuer) REFERENCES party (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE trust_subject (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

